function assertRouteGeometry(l){
 for(const a of l.nodes){assert(a.x>=0&&a.x+a.w<=l.width);for(const b of l.nodes)if(a!==b)assert(a.x+a.w<=b.x||b.x+b.w<=a.x||a.y+a.h+a.noteHeight<=b.y||b.y+b.h+b.noteHeight<=a.y);}
 for(const e of l.edges){
  const a=l.nodes.find(n=>n.id===e.from),b=l.nodes.find(n=>n.id===e.to);
  if(e.kind==='forward'){assert.equal(e.points.at(-1)[1],b.y);assert(e.points.at(-1)[0]>=b.x&&e.points.at(-1)[0]<=b.x+b.w);assert.equal(e.points[0][1],a.y+a.h);assert(e.d.includes('C'));}
  for(let j=1;j<e.segments.length;j++){const p=e.segments[j-1],q=e.segments[j],end=p.at(-1),u=[end[0]-p.at(-2)[0],end[1]-p.at(-2)[1]],v=[q[1][0]-q[0][0],q[1][1]-q[0][1]];assert.deepEqual(end,q[0]);assert(Math.abs(u[0]*v[1]-u[1]*v[0])<1e-6);assert(u[0]*v[0]+u[1]*v[1]>=0,'curve join reverses tangent');}
  for(const segment of e.segments)for(let i=0;i<=1000;i++){
   const t=i/1000,u=1-t,p=[0,1].map(k=>segment.length===2?u*segment[0][k]+t*segment[1][k]:u**3*segment[0][k]+3*u*u*t*segment[1][k]+3*u*t*t*segment[2][k]+t**3*segment[3][k]);
   for(const n of l.nodes)if(n!==a&&n!==b)assert(!(p[0]>n.x-1&&p[0]<n.x+n.w+1&&p[1]>n.y-1&&p[1]<n.y+n.h+n.noteHeight+1),'edge '+e.from+' -> '+e.to+' hits '+n.id);
  }
 }
}
